  <header ref="header" class="nlu-header" @keydown.esc="closeNavigation" @focusout="leaveHeader">
   <router-link class="nlu-brand" to="/p/nlu" aria-label="Next Level Up home"><img :src="safe(page?.branding?.logoUrl)||asset('logo.png')" alt="Next Level Up — Learning and Counseling Centers"/></router-link>
   <button ref="menuButton" class="nlu-menu" :aria-expanded="menuOpen" aria-controls="nlu-nav" @click="menuOpen=!menuOpen">{{menuOpen?'Close ×':'Menu ☰'}}</button>
   <nav id="nlu-nav" :class="{'is-open':menuOpen}" aria-label="Primary">
    <router-link v-for="[label,to] in nav" :key="to" :to="path(to)" :aria-current="section===to?'page':undefined">{{label}}</router-link>
    <div class="nlu-families" @mouseenter="hoverFamilies"><button ref="familiesButton" :aria-expanded="familiesOpen" aria-controls="nlu-families-menu" @click="familiesOpen=!familiesOpen">For Families <span aria-hidden="true">⌄</span></button>
     <div v-if="familiesOpen" id="nlu-families-menu" class="nlu-mega">
      <div v-for="[title,body,icon,links] in nluFamilies" :key="title" class="nlu-mega-column"><Icon :name="icon"/><h2>{{title}}</h2><p>{{body}}</p><router-link v-for="[label,to] in links" :key="to" :to="to.startsWith('/')?to:path(to)" @click="familiesOpen=false">{{label}} <span aria-hidden="true">›</span></router-link></div>
      <div class="nlu-mega-feature"><img :src="asset('family.png')" alt="A family talking with a counselor"/><h2>Not sure where to start?</h2><p>We’ll listen, answer your questions, and help you find the right path.</p><router-link class="nlu-button" :to="path('get-started')">Compare services →</router-link><router-link class="nlu-button nlu-light" :to="path('contact')">Talk with our team →</router-link></div>
      <div class="nlu-mega-bottom">Personalized support <span>Family-centered care</span><span>Qualified providers</span><span>Flexible options</span></div>
     </div>
    </div>
    <router-link :to="path('about')" :aria-current="section==='about'?'page':undefined">About</router-link>
    <PublicResourcesMenu :resources-path="path('resources')"/>
   </nav>
   <a class="nlu-button nlu-outline nlu-header-portal" :href="portalLoginUrl">Portal Login</a>
   <router-link class="nlu-button nlu-header-cta" to="/join/nlu">Join us →</router-link>
  </header>
  <main id="nlu-main">
   <div v-if="loading" class="nlu-wrap nlu-status" role="status">Loading Next Level Up…</div>
